const harga = { kopi: 18000, teh: 12000 };
function ambilHarga(menu) {
  return new Promise((res, rej) =>
    setTimeout(() => (harga[menu] ? res(harga[menu]) : rej(new Error(`Menu ${menu} tidak ada`))), 100)
  );
}
function pesan(menu) {
  return ambilHarga(menu);
  // rangkai then, catch, dan finally di sini
}
pesan("kopi").then(() => pesan("es"));

